-- A simple function returning a value
CREATE OR REPLACE FUNCTION calculate_tax(price NUMERIC, rate NUMERIC)
RETURNS NUMERIC AS $$
BEGIN
  RETURN ROUND(price * rate / 100, 2);
END;
$$ LANGUAGE plpgsql;

-- Call it
SELECT calculate_tax(99.99, 10);  -- 10.00

-- Function with conditional logic
CREATE OR REPLACE FUNCTION get_user_tier(total_spent NUMERIC)
RETURNS TEXT AS $$
BEGIN
  IF total_spent >= 1000 THEN
    RETURN 'platinum';
  ELSIF total_spent >= 500 THEN
    RETURN 'gold';
  ELSIF total_spent >= 100 THEN
    RETURN 'silver';
  ELSE
    RETURN 'bronze';
  END IF;
END;
$$ LANGUAGE plpgsql;

-- SQL functions (simpler, for single expressions)
CREATE OR REPLACE FUNCTION full_name(first TEXT, last TEXT)
RETURNS TEXT AS $$
  SELECT first || ' ' || last;
$$ LANGUAGE sql IMMUTABLE;

-- Most common trigger: auto-update updated_at timestamp
CREATE OR REPLACE FUNCTION set_updated_at()
RETURNS TRIGGER AS $$
BEGIN
  NEW.updated_at = NOW();
  RETURN NEW;  -- RETURN NEW applies the modified row
END;
$$ LANGUAGE plpgsql;

-- Attach to any table that has updated_at
CREATE TRIGGER trg_users_updated_at
BEFORE UPDATE ON users
FOR EACH ROW EXECUTE FUNCTION set_updated_at();

CREATE TRIGGER trg_posts_updated_at
BEFORE UPDATE ON posts
FOR EACH ROW EXECUTE FUNCTION set_updated_at();

